24	/** 1.0 = identical formality; falls off with spread. */
25	export function formalityCoherence(formalities: number[]): number {
26	  const f = formalities.filter((x) => typeof x === "number");
27	  if (f.length < 2) return 1;
28	  const spread = Math.max(...f) - Math.min(...f);
29	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
30	}
