32	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
33	  const colors = items.flatMap((i) => i.colors);
34	  const harmony = colorHarmonyScore(colors);
35	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
36	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
37	  const dna = items.length ? dnaHits / items.length : 0;
38	  const base = 0.45 * harmony + 0.35 * coherence + 0.2 * dna;
39	
40	  // With no lean the weight is 0, so scoring is byte-identical to before.
41	  const w = ctx.lean?.length ? LEAN_WEIGHT : 0;
42	  return Math.min(1, base * (1 - w) + w * leanScore(colors, ctx.lean ?? []));
43	}
