In `lib/ai/tagging-schema.ts`, change the schema. **Import order matters** — `vocab.ts` imports `TagSchema`, so `tagging-schema.ts` must NOT import from `vocab.ts` (that is a cycle). Define the two lists here and re-export them from vocab instead:

```ts
import { z } from "zod";

// Defined here rather than imported from lib/closet/vocab.ts: vocab derives
// CATEGORIES/SEASONS from this schema, so importing back would be a cycle.
// vocab.ts re-exports these two as the shared source.
export const MATERIALS = [
  "Cotton", "Wool", "Merino wool", "Cashmere", "Linen", "Silk", "Denim",
  "Leather", "Suede", "Canvas", "Corduroy", "Tweed", "Fleece", "Down",
  "Polyester", "Nylon", "Viscose", "Lyocell", "Stainless steel", "Gold",
  "Silver", "Rubber", "Other",
] as const;

export const TEXTURES = [
  "Flat", "Ribbed", "Cable knit", "Waffle", "Chunky knit", "Fine knit",
  "Brushed", "Fleece-back", "Twill", "Herringbone", "Quilted", "Pile",
] as const;

export const TagSchema = z.object({
  category: z.enum(["Tops", "Bottoms", "Outerwear", "Shoes", "Accessories", "Fragrance"]),
  subcategory: z.string().min(1),
  colors: z.array(z.string()).min(1).max(3),
  pattern: z.enum(["solid", "striped", "check", "print", "other"]),
  material: z.enum(MATERIALS),
  texture: z.enum(TEXTURES),
  formality: z.number().int().min(1).max(5),
  seasons: z.array(z.enum(["Spring", "Summer", "Autumn", "Winter"])).min(1),
});
export type Tags = z.infer<typeof TagSchema>;
```

Leave the existing `forStructuredOutput()` / `taggingJsonSchema` export below unchanged — it already strips the validation keywords, and `z.enum` emits only `enum`, which is supported.

