- [ ] **Step 3: Implement the normaliser**

Create `lib/closet/normalize-material.ts`:

```ts
import { MATERIALS } from "./vocab";

/**
 * Maps a legacy free-text material onto the constrained vocabulary.
 *
 * Longest-match-first so "merino wool" wins over "wool" — the reverse would
 * quietly downgrade every merino piece. "Unknown" was a fabrication written by
 * the old item-detail save path and is not a material, so it becomes null.
 */
export function normalizeMaterial(raw: string | null): string | null {
  if (!raw) return null;
  const s = raw.trim().toLowerCase();
  if (!s || s === "unknown") return null;

  const byLength = [...MATERIALS].sort((a, b) => b.length - a.length);
  const hit = byLength.find((m) => m !== "Other" && s.includes(m.toLowerCase()));
  return hit ?? "Other";
}
```

