import { OutfitDetail } from "@/components/outfits/outfit-detail";
import { MobileNav } from "@/components/shell/mobile-nav";

export default async function OutfitPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) redirect("/");

  // RLS scopes this to the owner — another user's id simply returns no row.
  const { data: outfit } = await supabase
    .from("outfits")
    .select("id, look_name, occasion, ai_reasoning, weather_snapshot, is_favorite")
    .eq("id", id)
    .maybeSingle();
  if (!outfit) notFound();

  const { data: links } = await supabase
    .from("outfit_items")
    .select("slot, items(id, name, subcategory, category, brand, image_url, cutout_url)")
    .eq("outfit_id", id);

  const rows = (links ?? []).map((l) => l.items).filter(Boolean);
  const signed = await signItemImages(rows.map(displayPath));

  const { data: logs } = await supabase
    .from("wear_logs")
    .select("worn_on")
    .eq("outfit_id", id);

  const weather = outfit.weather_snapshot as { tempC?: number; condition?: string } | null;

  return (
    <div className="flex min-h-dvh flex-1 flex-col">
      <OutfitDetail
        outfit={{
          id: outfit.id,
          lookName: outfit.look_name ?? "Today's look",
          occasion: outfit.occasion ?? "",
          weatherLabel: weather ? `${Math.round(weather.tempC ?? 0)}° ${weather.condition ?? ""}`.trim() : "",
          reasoning: outfit.ai_reasoning,
        }}
        pieces={rows.map((i) => ({
          id: i.id,
          name: i.name ?? i.subcategory ?? i.category,
          brand: i.brand,
          category: i.category,
          imageUrl: signed.get(displayPath(i)) ?? "",
        }))}
        worn={isWornToday(logs ?? [], localDateKey(new Date()))}
        favorite={outfit.is_favorite ?? false}
      />
      <MobileNav />
    </div>
  );
}
```

