```ts
import "server-only";
import { createClient } from "@/lib/supabase/server";
import { localDateKey } from "@/lib/outfits/local-date";
import { FREE, PRO, type Entitlements, type Tier } from "./tiers";

export { FREE, PRO };
export type { Entitlements, Tier };

/** Unknown input resolves to free: capabilities fail CLOSED. */
export function entitlementsFor(tier: unknown): Entitlements {
  return tier === "pro" ? PRO : FREE;
}

export function checkGenerations(
  e: Entitlements,
  usedToday: number,
): { allowed: boolean; remaining: number | null; reason?: string } {
  if (e.generationsPerDay == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.generationsPerDay - usedToday);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: "You've used today's looks. Pro gives you unlimited.",
      };
}

/**
 * The user's entitlements right now.
 *
 * Reads the tier from `profiles`. A read failure returns FREE rather than
 * throwing: a broken query must never take the app down, and handing out Pro on
 * an error is the wrong side to fail on.
 */
export async function currentEntitlements(): Promise<Entitlements> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return FREE;

  // Local override so Pro surfaces can be built and demoed before billing.
  if (process.env.NODE_ENV !== "production" && process.env.FITCHECK_FORCE_TIER) {
    return entitlementsFor(process.env.FITCHECK_FORCE_TIER);
  }

  const { data } = await supabase.from("profiles").select("tier").eq("id", user.id).single();
  return entitlementsFor(data?.tier);
}

/** How many model-spending generations this user has made on their local today. */
export async function generationsUsedToday(): Promise<number> {
  const supabase = await createClient();
  const { count } = await supabase
    .from("outfits")
    .select("id", { count: "exact", head: true })
    .eq("generated_on", localDateKey(new Date()));
  return count ?? 0;
}
```

> `generationsUsedToday` counts stored outfit rows for today. That is a **proxy**, not a ledger: a
> regenerate replaces rows rather than adding them, so it undercounts. Task 4 records why that is
> acceptable for now and what would replace it.

