import { currentEntitlements, generationsUsedToday, checkGenerations } from "@/lib/billing/entitlements";

/**
 * The single gate every real generation passes through.
 *
 * It was a deliberate no-op so that adding a paid tier later would be a change
 * to THIS file rather than surgery across the generate action. This is that
 * change: the decision now lives in lib/billing, and this stays the one call
 * site the generator knows about.
 */
export async function assertCanGenerate(_userId: string): Promise<void> {
  const e = await currentEntitlements();
  const used = await generationsUsedToday();
  const check = checkGenerations(e, used);
  if (!check.allowed) throw new QuotaExceededError(check.reason);
}

export class QuotaExceededError extends Error {
  constructor(message = "Daily generation limit reached") {
    super(message);
    this.name = "QuotaExceededError";
  }
}
