import { buildCandidates } from "../candidates";
import { rankTopN } from "../rank";

// Probe 2: a REALISTIC closet where scoring actually differentiates.
// Probe 1 used uniform colours, so every combo tied at 0.8 and clustering was
// invisible. Neutrals harmonise with everything, so combos containing them
// should score highest — the question is whether that collapses the shortlist
// onto one or two tops.

const TOP_COLORS = ["cream", "navy", "white", "charcoal", "rust", "olive", "burgundy", "camel", "pink", "yellow"];
const BOTTOM_COLORS = ["navy", "charcoal", "stone", "olive", "denim", "black"];
const SHOE_COLORS = ["brown", "black", "white", "tan"];

function realisticCloset() {
  const mk = (cat: string, i: number, color: string, f: number) => ({
    id: `${cat}-${i}-${color}`,
    category: cat,
    colors: [color],
    formality: f,
    seasons: [] as string[],
    material: "cotton",
  });
